const ST = () => { const o = ls("howabout.v1") || {}; o.dAll = dAll(o.d); o.d = {}; const L = LG(); Object.keys(o.dAll).forEach(k => { const i = k.lastIndexOf("|"); if (k.slice(i + 1) === L) o.d[k.slice(0, i)] = o.dAll[k]; });
  o.votes = o.votes || {}; o.vid = o.vid || {}; o.re = o.re || {}; o.props = o.props || []; o.win = o.win || {}; return o; };
const SAVE = o => { const all = Object.assign({}, o.dAll || {}), L = LG(); Object.keys(all).forEach(k => { if (k.endsWith("|" + L)) delete all[k]; }); Object.keys(o.d || {}).forEach(dt => { all[DKEY(dt, L)] = o.d[dt]; });
  const out = Object.assign({}, o, {d: all}); delete out.dAll; ls("howabout.v1", out); try { window.hvSyncMark && window.hvSyncMark("howabout.v1"); } catch(e){} };
