  const sh = document.querySelector(".ak-share:not([hidden])"); if (sh) sh.hidden = true; if (document.querySelector(".ak-globe:not([hidden])")) A().globeClose(); document.body.classList.remove("ak-on");
  if (!fromPop && location.hash === "#howabout"){ if (HIST) history.back(); else { const h = window.hvRt ? window.hvRt.now() : "boat"; try { history.replaceState({rt: 1}, "", location.pathname + location.search + "#" + (h === "howabout" ? "boat" : h)); } catch(e){} } }
