  h += (m.l0 ? A().levelsHTML(cur.lv) : `<p class="ha-sub c">${esc(PAST() ? T("这一题先用你自己的话说，想到什么说什么。", "For this one, just say it your own way — whatever comes to mind.") : T("今天先用你自己的话说，想到什么说什么。", "Today, just say it your own way — whatever comes to mind."))}</p>`) + `<div class="ha-frame"><div class="ha-sentw">${sentHTML()}</div>${buildHTML()}<div class="ha-tray c">${trayHTML(true)}</div>${A().micHTML(cur.said != null ? {done: cur.lv === 2 ? cur.said : composed().t || cur.said, real: cur.saidReal} : cur.lv === 2 ? {hint: T("点一下或按住，用你自己的话说", "Tap or hold — say it your way")} : null)}`;
