const recData = (r, date) => ({k: "ans", date, wk: r.w, d: r.i, q: r.q || "", l: r.l || "zh", t: r.t, p: r.p || "", nat: A().mother() || "", city: r.city || "", lon: r.ll ? r.ll[0] : null, lat: r.ll ? r.ll[1] : null, img: r.th || "", au: "", mime: "", pr: r.pr || null, late: r.late || 0});
